from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal("0")


def _decimal(value: Any) -> Decimal:
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _rounded_cents(value: Decimal) -> Decimal:
    result = value.quantize(_CENT, rounding=ROUND_HALF_UP)
    return Decimal("0.00") if result == 0 else result


def _required_precision(values: list[Decimal], line_count: int) -> int:
    width = 1
    for value in values:
        if not value.is_finite():
            continue
        parts = value.as_tuple()
        width = max(width, len(parts.digits) + max(parts.exponent, 0))
    return max(64, width * 3 + len(str(max(line_count, 1))) + 32)


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    live_values: list[tuple[int, Decimal, Decimal]] = []
    context_values = [
        _decimal(order.get("DISC_PCT", "")),
        _decimal(order.get("TOT_AMT", "")),
    ]

    for index, line in enumerate(lines):
        if line.get("DEL_FLG") == "Y":
            continue
        quantity = _decimal(line.get("QTY", ""))
        unit_price = _decimal(line.get("UNIT_PRC", ""))
        live_values.append((index, quantity, unit_price))
        context_values.extend((quantity, unit_price))

    audits: list[tuple[str, Any]] = []

    with localcontext() as context:
        context.prec = _required_precision(context_values, len(lines))

        total = _ZERO
        for index, quantity, unit_price in live_values:
            extension = _rounded_cents(quantity * unit_price)
            new_lines[index]["EXT_AMT"] = float(extension)
            total += extension

        discount_percent = _decimal(order.get("DISC_PCT", ""))
        discounted = _rounded_cents(
            total * (Decimal("100") - discount_percent) / Decimal("100")
        )

        incoming_total = _decimal(order.get("TOT_AMT", ""))
        new_order["TOT_AMT"] = float(discounted)

        if incoming_total != discounted:
            audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
